const input = $input.first().json;
const api = input.api;

// Rate limit definitions (requests per minute and daily caps)
const limits = {
  google_ads: { rpm: 60, daily: 15000 },
  meta_ads: { rpm: 200, daily: 50000 },
  hubspot: { rpm: 100, daily: 500000 },
  salesforce: { rpm: 25, daily: 15000 },
  ga4: { rpm: 60, daily: 50000 },
  gmail: { rpm: 250, daily: 1000000 },
  default: { rpm: 100, daily: 100000 }
};

const limit = limits[api] || limits.default;

// For MVP: always allow (rate limiting state requires persistent storage)
// In production: check against Redis/data table counters
return [{
  json: {
    allowed: true,
    api: api,
    limit: limit,
    current_usage: { rpm: 0, daily: 0 },
    message: 'Request allowed'
  }
}];

const result = $input.first().json;

return [{
  json: {
    allowed: result.allowed,
    api: result.api,
    limit: result.limit,
    current_usage: result.current_usage,
    message: result.message,
    checked_at: new Date().toISOString()
  }
}];
